#!/bin/bash
# The HUD's second batch of item icons (2026-10-14): what the HUD shows today as a stand-in (a craft step of an item
# with no icon -> hammer, a pick-up of an item with no icon -> star, Nether/End milestones -> star). Three 3x3 sheets
# with Codex's image tool, in the style of the first batch (art/items1.png, art/items2.png, art/skills1.png as
# references), one job at a time; then `ICONS_ONLY=1 node key.mjs` keys them into agent/assets/muse-ui/icons/ (names in
# key.mjs: items3, items4, items5).
# usage: ./gen-items-more.sh [items3|items4|items5 ...]   (no argument: all three, one after the other)
cd "$(dirname "$0")"
export NOCHAR=1
COMMON="A 3x3 grid of nine equal square cells (an icon sheet), one simple icon centered in each cell at the same size (about half the cell), in exactly the same polished sticker style as the reference icons (soft cel shading, thin dark plum outline, a small white shine), smooth rounded shapes, nothing blocky or pixelated, no cubes, no Minecraft look, clearly readable when shown very small (24 px): bold simple silhouettes, strong colour contrast, no tiny details. No faces on the icons. No letters, numbers or symbols anywhere. No green on any icon (the background is a green screen)."
REFS="art/items1.png art/items2.png art/skills1.png"
P_items3="$COMMON Row 1: a small sturdy wooden workbench (a light wooden table top with a little saw and a small hammer lying on it, four short legs); one plain straight wooden stick lying diagonally; a neat stack of three light oak wooden planks. Row 2: a squat rounded grey stone furnace with a glowing orange fire in its arched opening; a short sword with a light tan wooden blade and a darker wooden grip; an axe with a wooden handle and a light tan wooden head. Row 3: a short sword with a grey stone blade and a wooden grip; a wooden torch with a bright yellow-orange flame on top; a small closed wooden treasure chest with dark metal bands and a gold latch."
P_items4="$COMMON Row 1: a sharp dark grey flint shard with chipped facets; a small heap of grey and brown gravel pebbles; a rounded clump of brown soil with a few small pale pebbles in it. Row 2: a raw pink pork chop (raw meat with a white fat rim and a small bone); a sword with a bright silver-white iron blade and a wooden grip; one shiny gold ingot bar. Row 3: a rounded lump of rough dark crimson-red rock with a few darker pits; a glowing golden-orange rod with a few small ember sparks along it; a round dark teal-blue glass orb with a glowing golden-yellow slit iris in its centre (a magic marble)."
P_items5="$COMMON Row 1: a rounded chunk of very dark slate-grey cobbled stone (darker and bluer than ordinary cobblestone); a small heap of pale yellow sand; one shiny red apple with a short brown stem. Row 2: an axe with a wooden handle and a grey stone head; an axe with a wooden handle and a bright silver-white iron head; a soft fluffy white wool puff. Row 3: a small loose coil of white string; one white bone; a raw deep-red beef steak cut with a white fat edge (raw, not cooked)."
# items5's two axes came out as adzes (they read as pickaxes at 24 px): drawn again here after the wooden axe's shape
P_items6="$COMMON Row 1: an axe in exactly the same shape as the wooden axe in the reference sheet (a wooden handle and one broad wedge blade on one side, its curved cutting edge facing away from the handle, clearly an axe, not a pickaxe, hammer or adze) but with a grey stone blade; the same axe with a bright silver-white iron blade; a raw pale pink plucked chicken drumstick-shaped whole chicken (raw, not cooked). Row 2: a raw deep-pink lamb chop on a small bone (raw, not cooked); one soft white feather; a folded piece of brown leather hide. Row 3: one arrow with a grey stone tip and white fletching, diagonal; a small heap of dark grey powder; a silver-white iron chest armour piece (a breastplate with short shoulder guards)."
REFS6="art/items3.png art/items1.png art/skills1.png"
for s in ${@:-items3 items4 items5 items6}; do v="P_$s"; r="$REFS"; [ "$s" = items6 ] && r="$REFS6"; ./gen.sh "$s" "${!v}" $r; done
